    n = len(brackets)

    # Precompute balance and prefix/suffix inversions
    balance = [0] * (n + 1)
    inversions_left = [0] * (n + 1)
    inversions_right = [0] * (n + 1)

    for i in range(n):
        balance[i + 1] = balance[i] + (1 if brackets[i] == '(' else -1)
        inversions_left[i + 1] = inversions_left[i] + (1 if brackets[i] == ')' else 0)

    for i in range(n - 1, -1, -1):
        inversions_right[i] = inversions_right[i + 1] + (1 if brackets[i] == '(' else 0)

    # Check if it's already valid
    if balance[n] == 0:
        return "possible"

    # Check if a single inversion can fix the sequence
    for i in range(n):
