            # Inverting the current position
            if balance[i] + (1 if brackets[i] == ')' else -1) + balance[n] == 0:
                return "possible"

        # Check inversions that fix the segment [0, i] or [i+1, n-1]
        if balance[i] + inversions_right[i + 1] == 0 or balance[i + 1] + inversions_left[i] == 0:
            return "possible"

    return "impossible"

